def stochastic(data, window, smooth):
  low14 = data['Low'].rolling(window).min()
  high14 = data['High'].rolling(window).max()
  k = ((data['Close'] - low14) / (high14 - low14)) * 100
  d = k.rolling(smooth).mean()
